import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CBgCDFlD.js";const u=JSON.parse('{"title":"Design system","description":"","frontmatter":{},"headers":[],"relativePath":"docs/design-system.md","filePath":"docs/design-system.md"}'),r={name:"docs/design-system.md"};function s(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="design-system" tabindex="-1">Design system <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design system&quot;">​</a></h1><p>The app is calm and rounded, like the plush: one blue accent for actions, white or near-white surfaces, and only Poulpy and the Home header tint with his mood. Values live in <a href="https://github.com/tkint/coach-poulpy/blob/main/design/tokens.json" target="_blank" rel="noreferrer"><code>design/tokens.json</code></a> and are generated into each platform (see <a href="./../design/README"><code>design/README.md</code></a>); this page says how to use them. The live swatches are on the site&#39;s Tokens page.</p><h2 id="colour-roles" tabindex="-1">Colour roles <a class="header-anchor" href="#colour-roles" aria-label="Permalink to &quot;Colour roles&quot;">​</a></h2><p>Use roles, never raw palette steps, in screens. Each role has a light and a dark value.</p><table tabindex="0"><thead><tr><th>Role</th><th>Use it for</th></tr></thead><tbody><tr><td><code>primary</code> / <code>onPrimary</code></td><td>The main action on a screen (Start session, Save), selected chips, links, progress</td></tr><tr><td><code>primaryContainer</code> / <code>onPrimaryContainer</code></td><td>Tonal buttons, selected rows, Poulpy&#39;s speech on the blue side</td></tr><tr><td><code>grumpy</code> / <code>onGrumpy</code></td><td>The one action offered while Poulpy is on the ember side (Catch up, Flip him back)</td></tr><tr><td><code>grumpyContainer</code> / <code>onGrumpyContainer</code></td><td>The Home header and cards while Poulpy is on the ember side</td></tr><tr><td><code>background</code>, <code>surface</code>, <code>surfaceVariant</code></td><td>Screen, cards and sheets, inset fields and steppers</td></tr><tr><td><code>onSurfaceVariant</code>, <code>outline</code></td><td>Secondary text and captions; card borders and dividers</td></tr><tr><td><code>success</code></td><td>A confirmed save or a finished phase, with a check icon</td></tr><tr><td><code>error</code> / <code>onError</code></td><td>Errors only: crimson, always with an icon and words</td></tr></tbody></table><p>Rules:</p><ul><li><code>poulpy.blue</code>, <code>poulpy.ember</code> and <code>poulpy.ink</code> are Poulpy&#39;s fabric and never change between light and dark.</li><li>The plush blue and ember are too light for white text: buttons use <code>primary</code> and <code>grumpy</code>.</li><li>Ember means &quot;a session slipped&quot;, never &quot;something broke&quot;. An error is crimson, so a cross Poulpy is never read as a failure.</li><li>Colours that must be told apart also differ in lightness, not hue alone.</li></ul><h2 id="mood-shades" tabindex="-1">Mood shades <a class="header-anchor" href="#mood-shades" aria-label="Permalink to &quot;Mood shades&quot;">​</a></h2><p>Six shades, from <code>mood.*</code>, only on Poulpy himself, the Home header tint and mood-coloured charts:</p><table tabindex="0"><thead><tr><th>Side</th><th>Shades, calmest to strongest</th></tr></thead><tbody><tr><td>Blue (on track)</td><td><code>recovering</code>, <code>happy</code>, <code>proud</code></td></tr><tr><td>Ember (a session slipped)</td><td><code>annoyed</code>, <code>grumpy</code>, <code>fuming</code></td></tr></tbody></table><p>Which shade shows when is in <a href="./brand#moods">Brand</a>.</p><h2 id="type" tabindex="-1">Type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type&quot;">​</a></h2><p>Baloo 2 for display and titles, Nunito for everything else. Platforms map each role to a system text style so Dynamic Type and font scaling keep working (<code>.font(.poulpy(.headline))</code> on iOS, <code>MaterialTheme.typography</code> on Android).</p><table tabindex="0"><thead><tr><th>Role</th><th>Font</th><th>Size / line</th><th>Use</th></tr></thead><tbody><tr><td><code>display</code></td><td>Baloo 2 800</td><td>40 / 44</td><td>Poulpy&#39;s line on Home, end-of-session headline</td></tr><tr><td><code>title</code></td><td>Baloo 2 700</td><td>28 / 32</td><td>Screen titles, workout name on its page</td></tr><tr><td><code>headline</code></td><td>Baloo 2 700</td><td>21 / 25</td><td>Section heads, the current exercise in the player</td></tr><tr><td><code>body</code></td><td>Nunito 500</td><td>16 / 24</td><td>Everything you read</td></tr><tr><td><code>label</code></td><td>Nunito 800, tracked 0.08 em, upper case</td><td>12.5 / 16</td><td>Eyebrows, tab labels, &quot;Next up&quot;</td></tr><tr><td><code>timer</code></td><td>Nunito 800, tabular figures</td><td>64 / 64</td><td>Timers and rep counts, which must not jitter</td></tr></tbody></table><h2 id="space-radius-motion" tabindex="-1">Space, radius, motion <a class="header-anchor" href="#space-radius-motion" aria-label="Permalink to &quot;Space, radius, motion&quot;">​</a></h2><ul><li>Spacing steps: 4, 8, 12, 16, 24, 32, 48 (<code>xs</code> to <code>xxxl</code>). Pick a step; never a value between them.</li><li>Radius: 10 for chips and small fields, 16 for cards, 24 for sheets, pill for buttons.</li><li>Motion: the flip (700 ms with overshoot) is the one signature move, used only when Poulpy changes side. Mood shades fade in 300 ms. Everything else is 150 to 250 ms and plain. With reduced motion on, the loader slows to one turn in 10 s.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Shape</th><th>Notes</th></tr></thead><tbody><tr><td>Primary button</td><td>56 high, pill, <code>primary</code></td><td>One per screen</td></tr><tr><td>Tonal button</td><td>56 high, pill, <code>primaryContainer</code></td><td>Secondary actions</td></tr><tr><td>Outline button</td><td>56 high, pill, 2 px <code>outline</code></td><td>Cancel, less important choices</td></tr><tr><td>Grumpy button</td><td>56 high, pill, <code>grumpy</code></td><td>Only the catch-up action while Poulpy is ember</td></tr><tr><td>Chip</td><td>36 high, pill; on = <code>primary</code>, off = 1.5 px <code>outline</code></td><td>Filters (muscle, equipment, format), with <code>aria-pressed</code> or selected state; <code>PoulpyChip</code> on both platforms</td></tr><tr><td>Search field</td><td>48 high, pill, 1.5 px <code>outline</code>, <code>primary</code> while it holds text, a round clear button</td><td><code>PillSearchField</code> on both platforms</td></tr><tr><td>Stepper</td><td>Inset <code>surfaceVariant</code> box, label, minus and plus round buttons of 44</td><td>Sets, reps, load, rest</td></tr><tr><td>Pattern badge</td><td>44 round, <code>primaryContainer</code>, one icon per movement pattern in <code>onPrimaryContainer</code></td><td>Stands in for exercise pictures until real images exist</td></tr><tr><td>Filter row</td><td>Search field, a row of chips, then the count line with one action at its right</td><td><code>ListFilters</code> on both platforms, shared by the exercise and workout lists</td></tr><tr><td>Poulpy card</td><td>24 radius, <code>primaryContainer</code>, Poulpy happy on the blue side, a title, a line and one primary button</td><td><code>PoulpyCard</code>: no results, an empty list</td></tr><tr><td>Item menu</td><td>A long press (iOS context menu) or ⋮; actions with icons, a divider, then the destructive one</td><td>Destructive items and their confirmation are <code>error</code> with an icon, never ember; the confirmation says what goes and what stays</td></tr><tr><td>Plan sheet</td><td>24 radius sheet, a month from Monday; past days dimmed, today outlined, planned days <code>primary</code></td><td><code>PlanSheet</code> on both platforms; tick several days, save once</td></tr><tr><td>Error banner</td><td><code>error</code> tint, icon plus text</td><td>Never ember</td></tr><tr><td>Loader</td><td>Poulpy from above, a blue outline of eight lobes, one turn every 2.4 s</td><td><code>PoulpyLoader</code> on both platforms; replaces spinners</td></tr></tbody></table><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><p>Mockups are plain HTML pages in <code>design/mockups/</code> (<a href="./adr/0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>): drafts in <code>drafts/</code>, validated screens in <code>agreed/</code>, each split into <code>phone/</code>, <code>tablet/</code> and <code>web/</code>. The docs site shows them on the <a href="https://tkint.github.io/coach-poulpy/mockups/" target="_blank" rel="noreferrer">Mockups</a> pages, one page per screen, in light or dark. Build a screen from its agreed mockup, and get a mockup agreed, through a PR that moves it out of <code>drafts/</code>, before building a screen that has none. Until the existing screens are converted, the mockups canvas in the Claude project still holds them: Home (planned, done, nothing planned), Library (workouts, exercises, search, long-press actions, empty), workout page (menu, plan days, delete), exercise detail, builder, the guided player (ready, set, rest, finished), Live and its summary, History (calendar, stats), session detail, and Settings (general, devices, data sources).</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>Touch targets at least 44 by 44.</li><li>Text contrast at least 4.5:1, including small grey labels; 3:1 only for text 24 px and up.</li><li>Every icon-only button has a label; decorative drawings of Poulpy are hidden from screen readers, and a pose that carries meaning has a description.</li><li>Nothing depends on colour alone: mood changes also change Poulpy&#39;s face and words, errors carry an icon.</li></ul>',22)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
